protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // Preserve "Discriminator" property name used by existing documents
    // (EF Core 9 defaults to "$type")
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

    // Preserve "Blog|<key>" id format used by existing documents
    // (EF Core 9 defaults to key-only ids)
    modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

    // HasIndex removed — Cosmos DB does not support EF-managed indexes;
    // EF Core 9 now throws instead of silently ignoring it.
    // Manage indexing policy via Azure Portal, Bicep, or Terraform.
}

